<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';$user=require_role('guru');$pdo=db();$selected=normalize_class_name((string)($_GET['kelas']??'1A'));if(!in_array($selected,all_class_names(),true))$selected='1A';$stmt=$pdo->prepare('SELECT * FROM students WHERE kelas=? ORDER BY nama_lengkap');$stmt->execute([$selected]);$students=$stmt->fetchAll();$surah=$pdo->prepare('SELECT * FROM surah_curriculum WHERE tahun_ajaran=? ORDER BY level,urutan');$surah->execute([ACTIVE_ACADEMIC_YEAR]);$surahs=$surah->fetchAll();$scores=$pdo->prepare('SELECT t.* FROM laporan_tahsin_tahfidz t JOIN students s ON s.id=t.student_id WHERE s.kelas=? ORDER BY t.tanggal DESC');$scores->execute([$selected]);$scoreRows=$scores->fetchAll();$latest=[];foreach($scoreRows as $row){$latest[$row['student_id']][$row['nama_surah']]??=$row;}$pageTitle='Data Kelas';require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><p class="eyebrow">Pengelolaan Kelas</p><h1 class="page-title">Data Nilai & Laporan Harian</h1><p class="page-description">Tabel kelas 1A–6B berdasarkan level, nilai per surat, serta presensi dan tadarus.</p></div></div><section class="card"><div class="class-buttons"><?php foreach(all_class_names() as $name):?><a class="class-button <?= $name===$selected?'active':'' ?>" href="<?= url('guru/classes.php?kelas='.$name) ?>"><?= $name ?></a><?php endforeach;?></div></section><section class="card" style="margin-top:20px"><div class="filter-row"><div><p class="eyebrow">Kelas <?= e($selected) ?></p><h2 style="font-size:28px;margin:3px 0">Nilai per Surat</h2><span class="muted"><?= count($students) ?> siswa tampil.</span></div><a class="btn btn-primary" href="<?= url('guru/daily-reports.php?kelas='.$selected) ?>">Isi Nilai / Laporan</a></div><div class="table-wrap"><table class="table" style="min-width:1400px"><thead><tr><th>No</th><th>Nama Peserta Didik</th><th>Level</th><?php foreach(array_slice($surahs,0,12) as $item):?><th><?= e($item['nama_surah']) ?><br><small>Rata-rata</small></th><?php endforeach;?></tr></thead><tbody><?php foreach($students as $index=>$student):?><tr><td><?= $index+1 ?></td><td class="name"><?= e($student['nama_lengkap']) ?><br><small class="muted">NIS <?= e($student['nis']) ?></small></td><td><?= e(level_name($student['level'])) ?></td><?php foreach(array_slice($surahs,0,12) as $item):$score=$latest[$student['id']][$item['nama_surah']]??null;?><td><?= $score?e((string)$score['nilai_rata_rata']):'-' ?></td><?php endforeach;?></tr><?php endforeach;?><?php if(!$students):?><tr><td colspan="15"><div class="empty"><strong>Belum ada siswa di kelas <?= e($selected) ?></strong>Impor data melalui Daftar Siswa.</div></td></tr><?php endif;?></tbody></table></div></section><?php require ROOT_PATH.'/includes/footer.php';?>

